SELECT id, title, source_type, author, edition, url, note FROM jsonb_populate_recordset(NULL::public.source, '[{"title": "旧五代史·卷80·晋高祖本纪·天福七年六月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/jiuwudaishi-080-942-shi-death/source.txt", "note": "《旧五代史》卷80·晋高祖本纪·天福七年六月，段落 jiu-wudaishi-205deb4a7860-p001972；已核上下文及传主，纸本及异文待核。", "id": "6412688d-1b3d-50cd-a435-6bd87a5c7e45"}, {"title": "旧五代史·卷81·晋少帝本纪·天福七年七月", "source_type": "primary", "author": "薛居正等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/jiuwudaishi-081-942-july/source.txt", "note": "《旧五代史》卷81·晋少帝本纪·天福七年七月，段落 jiu-wudaishi-205deb4a7860-p001979；已核上下文及传主，纸本及异文待核。", "id": "b7b14474-1abf-56dc-af9e-5d9a82a042b6"}, {"title": "新五代史·卷9·晋本纪·天福七年", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/xinwudaishi-009-942-succession/source.txt", "note": "《新五代史》卷9·晋本纪·天福七年，段落 xin-wudaishi-b08f244b9241-p000333；已核上下文及传主，纸本及异文待核。", "id": "ce49f762-1a4b-5f35-8f95-f69e69f10973"}, {"title": "新五代史·卷17·晋家人传·石重睿", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/xinwudaishi-017-chongrui-succession/source.txt", "note": "《新五代史》卷17·晋家人传·石重睿，段落 xin-wudaishi-b08f244b9241-p000599；已核上下文及传主，纸本及异文待核。", "id": "17c4e031-e305-5aef-b5e8-4fa0608a06a7"}, {"title": "新五代史·卷62·南唐世家·宋齐丘出镇", "source_type": "primary", "author": "欧阳修", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/03f32f35d226d0f16dc68b58596ef35b6835b720/content/books/zizhi-tongjian/vol-283/year-0942/part-03/sources/library/xinwudaishi-062-song-hongzhou/source.txt", "note": "《新五代史》卷62·南唐世家·宋齐丘出镇，段落 xin-wudaishi-b08f244b9241-p003140；已核上下文及传主，纸本及异文待核。", "id": "82be0c93-cfe2-54a1-881b-58f43cefab95"}, {"title": "资治通鉴·卷283·天福七年五月及随后记载", "source_type": "primary", "author": "司马光等", "edition": "选定TXT逐字导出；电子本，纸本及异文待核。", "url": "https://github.com/greed-216/histree/blob/38b9b714bc0e6ccbbdf52f39b27d882bbd9c97f2/content/books/zizhi-tongjian/vol-283/year-0942/part-02/sources/library/tongjian-283-942-may/source.txt", "note": "《资治通鉴》卷283·天福七年五月及随后记载，段落 zizhi-tongjian-a63549944a71-p003362；已核上下文及传主，纸本及异文待核。", "id": "a8961b3a-0c9f-51bc-b3b0-02c2f424bd15"}]'::jsonb)
