INSERT INTO public.person (id, name, aliases, era, birth_year, death_year, description, biography, status)
SELECT id, name, aliases, era, birth_year, death_year, description, biography, status FROM jsonb_populate_recordset(NULL::public.person, '[{"name": "宋齐丘", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化二年条所见人物：宋齐丘。", "biography": null, "status": "draft", "id": "313ec6c3-7027-5fef-8b5d-b79d259f9c8a"}, {"name": "李昪", "aliases": ["徐知诰", "知诰"], "era": "晚唐", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷260乾宁二年条所见人物：李昪。", "biography": null, "status": "draft", "id": "5a8b1ad8-1e2e-5318-ae39-1ab3a3e244f9"}, {"name": "徐景遂", "aliases": ["景遂"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：徐景遂，获任者。", "biography": null, "status": "draft", "id": "cb45cc6e-58fb-5804-8c3d-962cbbc03a13"}, {"name": "石敬瑭", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：石敬瑭。", "biography": null, "status": "draft", "id": "bf42d98c-7477-5be1-a767-867fe26cf617"}, {"name": "石重睿", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "石敬瑭的幼子。942年石敬瑭病中让他拜见冯道，并由宦者抱入冯道怀中；史书解释为托付之意。石敬瑭去世后，大臣以多事为由拥立石重贵，石重睿未能继位。生卒年未载。", "biography": null, "status": "draft", "id": "361f2434-8f22-5818-b912-366e1a3e8af8"}, {"name": "冯道", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷268乾化元年条所见人物：冯道。", "biography": null, "status": "draft", "id": "16b195e8-f15a-5814-bdd2-934f10bbdf39"}, {"name": "景延广", "aliases": ["景延廣"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：景延广，原客将、获任者。", "biography": null, "status": "draft", "id": "de8a964e-a028-50ee-8d54-2cbfda481e98"}, {"name": "石重贵", "aliases": ["石重貴"], "era": "五代十国", "birth_year": 914, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：石重贵，被叙侄子及养子身份者。", "biography": null, "status": "draft", "id": "2741e60a-9bf9-56a7-b30d-3db439caa139"}, {"name": "刘知远", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "《资治通鉴》卷271贞明五年条所见人物：刘知远。", "biography": null, "status": "draft", "id": "69fa3b4b-2f0d-5799-bbf5-e378af9816e1"}, {"name": "刘氏（石敬瑭太妃）", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "后晋皇太妃。942年五月乙巳被尊为皇太后。《资治通鉴》称她是石敬瑭的庶母，《旧五代史》所引徐无党注称生母，关系异说保留。姓名及出生年未载。", "biography": null, "status": "draft", "id": "57ccf847-6548-50a3-9346-b099fc0def3d"}, {"name": "永宁公主（石敬瑭妻）", "aliases": ["永宁公主", "永寧公主"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：永宁公主（石敬瑭妻），与从荣异母的公主。", "biography": null, "status": "draft", "id": "fddc7a96-9cc5-5313-ac24-2c3189930825"}, {"name": "王延政", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "本批《资治通鉴》与二十四史所见人物：王延政，都教练使、赴建州抚慰者。", "biography": null, "status": "draft", "id": "83601670-f3dc-5559-b599-e39bda91eb6c"}, {"name": "王延羲", "aliases": ["王曦"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国宗室，王继鹏的叔父，曾任左仆射、同平章事。939年被政变军队拥立，自称威武节度使、闽国王，更名王曦，改元永隆。生卒年暂未核实。", "biography": null, "status": "draft", "id": "e706d6ae-56f4-5e44-9d24-f3060ae87cbb"}, {"name": "林守亮", "aliases": [], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国将领。942年受王延羲派遣进入尤溪，配合袭建州的计划。七月尤口战败后逃回。生卒年未载。", "biography": null, "status": "draft", "id": "24c424ba-bfac-53f6-99e8-89ac45a0ffa7"}, {"name": "黄敬忠", "aliases": ["黃敬忠"], "era": "五代十国", "birth_year": null, "death_year": 942, "description": "闽国大明宫使。942年屯兵尤口，准备配合袭击建州；七月丁酉听从占者所言而按兵不动，遭包洪实等水陆夹攻后被杀。出生年未载。", "biography": null, "status": "draft", "id": "78f91d3c-cf41-5217-bd69-94dd0ff2bc8b"}, {"name": "黄绍颇", "aliases": ["黃紹頗"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "闽国官员，连江人。陈匡范借款补额一事暴露后，王延羲任黄绍颇为国计使。黄绍颇建议对不属荫补的求官者按条件收钱授官，王延羲接受。具体年月和生卒年未载。", "biography": null, "status": "draft", "id": "534bfbe9-b7bc-5b90-8054-1bb004f6b7c7"}, {"name": "包洪实", "aliases": ["包洪實"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政部将。942年与陈望率水军抵御福州军，七月丁酉在尤口引兵登岸，水陆夹攻并取胜。生卒年未载。", "biography": null, "status": "draft", "id": "6611bd02-2511-5cbf-b838-78ae09cac989"}, {"name": "陈望", "aliases": ["陳望"], "era": "五代十国", "birth_year": null, "death_year": null, "description": "王延政部将。942年与包洪实率水军抵御福州军，七月丁酉在尤口与对方交战。生卒年未载。", "biography": null, "status": "draft", "id": "1129ee15-bc93-5f0e-bb19-5143390129ac"}]'::jsonb)
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.event (id, title, start_year, end_year, time_original, dynasty, description, phases, location_name, location_modern_name, location_lat, location_lng, location_precision, location_note, status)
