: 942, "end_year": 942, "time_original": "942年五月丙午", "dynasty": "五代十国", "description": "李昪任宋齐丘为镇南节度使。", "phases": [], "location_name": "洪州", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "985f8fe4-bd82-594e-b71e-a4345a92cc98"}, {"title": "石敬瑭病中让石重睿拜冯道，再由宦者抱入冯道怀中", "start_year": 942, "end_year": 942, "time_original": "942年石敬瑭病中、六月去世以前，具体日期未载", "dynasty": "五代十国", "description": "石敬瑭病中，冯道单独入见。皇帝让幼子石重睿出来拜冯道，又命宦者将孩子抱入冯道怀中。《资治通鉴》认为皇帝大概希望冯道辅立石重睿。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "148c2e0d-3b97-5665-9173-97527abf1ca2"}, {"title": "石敬瑭去世", "start_year": 942, "end_year": 942, "time_original": "942年六月乙丑", "dynasty": "五代十国", "description": "石敬瑭去世。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "12390f8f-7439-5b51-a624-e0130f1a9527"}, {"title": "冯道与景延广认为国家多难，应立成年君主，拥立石重贵", "start_year": 942, "end_year": 942, "time_original": "942年六月乙丑，石敬瑭去世当日", "dynasty": "五代十国", "description": "冯道与景延广认为国家多难，应立成年君主，拥立石重贵。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "c18c6d47-47b4-53b7-b2ad-e1fcdfa889d7"}, {"title": "石重贵即皇帝位", "start_year": 942, "end_year": 942, "time_original": "942年六月乙丑", "dynasty": "五代十国", "description": "石重贵即皇帝位。", "phases": [], "location_name": "五代十国", "location_modern_name": null, "location_lat": null, "location_lng": null, "location_precision": "unknown", "location_note": "采用史书记载的地点名称，地理坐标尚未核实。", "status": "draft", "id": "92d66904-5d89-